CREATE TABLE sales (
  id INTEGER PRIMARY KEY,
  category TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  unit_price_cents INTEGER NOT NULL
);
INSERT INTO sales VALUES
  (1, 'book', 2, 1250), (2, 'book', 1, 2500), (3, 'tool', 3, 400);
SELECT category, SUM(quantity * unit_price_cents) AS revenue_cents
FROM sales GROUP BY category ORDER BY category;

CREATE TABLE orders (id INTEGER PRIMARY KEY, total_cents INTEGER NOT NULL);
CREATE TABLE items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL);
INSERT INTO orders VALUES (1, 3000), (2, 3000);
INSERT INTO items VALUES (11, 1), (12, 1), (21, 2);
SELECT SUM(o.total_cents)
FROM orders AS o JOIN items AS i ON i.order_id = o.id;

CREATE TABLE customers (id INTEGER PRIMARY KEY, customer_code TEXT NOT NULL);
INSERT INTO customers VALUES (1, '00123');
SELECT customer_code, typeof(customer_code) FROM customers;

PRAGMA foreign_keys = ON;
CREATE TABLE people (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE workshops (id INTEGER PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE bookings (
  person_id INTEGER NOT NULL REFERENCES people(id) ON DELETE RESTRICT,
  workshop_id INTEGER NOT NULL REFERENCES workshops(id) ON DELETE RESTRICT,
  PRIMARY KEY (person_id, workshop_id)
);
INSERT INTO people VALUES (1, 'Mira');
INSERT INTO workshops VALUES (10, 'SQL'), (20, 'Testing');
INSERT INTO bookings VALUES (1, 10), (1, 20);
SELECT p.name, w.title
FROM bookings AS b
JOIN people AS p ON p.id = b.person_id
JOIN workshops AS w ON w.id = b.workshop_id
ORDER BY w.id;

CREATE TABLE reservations (
  id INTEGER PRIMARY KEY,
  seats INTEGER NOT NULL CHECK (seats BETWEEN 1 AND 4)
);
INSERT INTO reservations VALUES (1, 2);

CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  balance_cents INTEGER NOT NULL CHECK (balance_cents >= 0)
);
INSERT INTO accounts VALUES (1, 1200), (2, 300);
BEGIN;
UPDATE accounts SET balance_cents = balance_cents - 200 WHERE id = 1;
UPDATE accounts SET balance_cents = balance_cents + 200 WHERE id = 2;
COMMIT;
SELECT id, balance_cents FROM accounts ORDER BY id;

